mapper.update:
UPDATE menu_role_perm
SET
    disp_yn  = #{dispYn}    
    , view_yn = #{viewYn}   
    , ins_yn  = #{insYn}    
    , upd_yn  = #{updYn}    
    , del_yn  = #{delYn}    
    , mod_user = #{modUser} 
    , mod_date = NOW()      
WHERE menu_no = #{menuNo}
  AND role_no = #{roleNo}

mapper.select:
WITH RECURSIVE menu_tree AS ( -- [1] 가상 테이블 정의 시작 SELECT m.menu_no AS menuNo , m.menu_name AS menuName , m.parent_no AS parentNo , m.menu_lev AS menuLev , m.sort_ord AS sortOrd , m.pro_no AS proNo , CAST(LPAD(m.sort_ord, 5, '0') AS CHAR(200)) AS path FROM menu m WHERE (m.parent_no IS NULL OR m.parent_no = 0) AND m.use_yn = 'Y'
UNION ALL
-- 자기 자신을 이용해 계속 조회(재귀 SELECT m.menu_no , m.menu_name , m.parent_no , m.menu_lev , m.sort_ord , m.pro_no , CONCAT(mt.path, '/', LPAD(m.sort_ord, 5, '0')) FROM menu m JOIN menu_tree mt ON m.parent_no = mt.menuNo WHERE m.use_yn = 'Y' -- [2] 가상 테이블 정의 끝 ) -- [3] 메인 호출 쿼리 SELECT mt.menuNo AS menuNo , mt.menuName AS menuName , mt.parentNo AS parentNo , mt.menuLev AS menuLev , mt.sortOrd AS sortOrd , mrp.perm_no AS permNo , mrp.disp_perm AS dispPerm , mrp.view_perm AS viewPerm , mrp.ins_perm AS insPerm , mrp.upd_perm AS updPerm , mrp.del_perm AS delPerm FROM menu_tree mt LEFT JOIN menu_role_perm mrp ON mt.menuNo = mrp.menu_no AND mrp.role_no = #{roleNo} ORDER BY mt.path;
